#!/usr/bin/env perl
use strict;use warnings;use Cwd qw(abs_path);use Digest::SHA;use Fcntl qw(:flock);use File::Basename qw(dirname);use File::Path qw(make_path remove_tree);use File::Temp qw(tempdir);use Getopt::Long;use IO::Select;use IO::Socket::UNIX;use IPC::Open3;use JSON::PP;use POSIX qw(WNOHANG);use Socket qw(SOCK_STREAM);use Symbol qw(gensym);use Time::HiRes qw(clock_gettime CLOCK_MONOTONIC);
my $json=JSON::PP->new->canonical->pretty;my($config_path,$out,$startup,$lock_fd);GetOptions('config=s'=>\$config_path,'out=s'=>\$out,'startup-only'=>\$startup,'lock-fd=i'=>\$lock_fd) or die "invalid options\n";die "usage: $0 --config CONFIG.json --out NEWDIR [--startup-only] [--lock-fd N]\n" unless $config_path&&$out&&!@ARGV;
sub read_text{open my $f,'<:raw',$_[0] or die "open $_[0]: $!\n";local $/;my $s=<$f>;close $f;return $s//'';}
sub save{open my $f,'>:raw',$_[0] or die "write $_[0]: $!\n";print {$f} $json->encode($_[1]) or die "write: $!\n";close $f or die "close: $!\n";}
sub now{clock_gettime(CLOCK_MONOTONIC)}
sub command{my($argv)=@_;my $err=gensym;my $pid=open3(my $in,my $stdout,$err,@$argv);close $in;my $sel=IO::Select->new($stdout,$err);my %kind=(fileno($stdout)=>'stdout',fileno($err)=>'stderr');my %text=(stdout=>'',stderr=>'');my $end=now()+20;
 while($sel->count){if(now()>$end){kill 'TERM',$pid;select undef,undef,undef,.1;kill 'KILL',$pid;waitpid($pid,0);return {argv=>$argv,exit=>124,%text};}for my $f($sel->can_read(.2)){my $fd=fileno($f);my $n=sysread($f,my $buf,65536);die "read: $!\n" unless defined $n;if(!$n){$sel->remove($f);close $f;}else{$text{$kind{$fd}}.=$buf;}}}waitpid($pid,0);return {argv=>$argv,exit=>($?&127?128+($?&127):$?>>8),%text};}
sub proc{my($pid)=@_;my $s=read_text("/proc/$pid/stat");$s=~/\A\d+ \((.*)\) (.*)\z/s or die "bad proc $pid\n";my @f=split /\s+/,$2;my $exe=readlink("/proc/$pid/exe")//die "missing exe $pid\n";my $w=read_text("/proc/$pid/wchan");$w=~s/\s+$//;return {pid=>0+$pid,start_ticks=>"$f[19]",state=>$f[0],ppid=>0+$f[1],exe=>$exe,wchan=>$w};}
sub sameproc{my($old)=@_;my $p=proc($old->{pid});die "PID identity changed\n" unless $p->{start_ticks} eq "$old->{start_ticks}"&&$p->{exe} eq $old->{exe};return $p;}
sub hashfile{open my $f,'<:raw',$_[0] or die "open hash $_[0]: $!\n";my $h=Digest::SHA->new(256)->addfile($f)->hexdigest;close $f;return {path=>abs_path($_[0]),bytes=>-s $_[0],sha256=>$h};}
sub one{my($sock,$cmd)=@_;my $s=IO::Socket::UNIX->new(Type=>SOCK_STREAM,Peer=>$sock,Timeout=>5) or die "connect $sock: $!\n";$s->autoflush(1);print {$s} "$cmd\n" or die "write socket: $!\n";my $sel=IO::Select->new($s);die "socket timeout\n" unless $sel->can_read(10);my $line=<$s>;close $s;die "bad response $cmd\n" unless defined($line)&&$line!~/^error/;chomp $line;return $line;}
my $cfg=$json->decode(read_text($config_path));die "config must be an object\n" unless ref($cfg) eq 'HASH';for(qw(core library cubin trace_cubin ple_file source_sha dirty_patch weight_manifest build_record launch_environment holder_manifests)){die "missing config $_\n" unless exists $cfg->{$_};}
die "full source SHA required\n" unless $cfg->{source_sha}=~/\A[0-9a-f]{40}\z/;die "six holder manifests required\n" unless ref($cfg->{holder_manifests}) eq 'ARRAY'&&@{$cfg->{holder_manifests}}==6;
for(qw(core library cubin trace_cubin ple_file dirty_patch weight_manifest build_record)){$cfg->{$_}=abs_path($cfg->{$_})//die "resolve $_\n";}for(@{$cfg->{holder_manifests}}){$_=abs_path($_)//die "resolve holder\n";}
my $env=$cfg->{launch_environment};die "explicit launch_environment object required\n" unless ref($env) eq 'HASH';for(qw(PATH FLASH_MAXT CUDA_VISIBLE_DEVICES CUDA_DEVICE_ORDER FLASH_PLE_DISK FLASH_PLE_OFF FLASH_MAXIMG FLASH_NBLK SPLIT_SHARES ATTN_MAP)){die "missing environment $_\n" unless defined $env->{$_};}for(keys %$env){die "invalid environment $_\n" if ref($env->{$_})||$env->{$_}=~/[\x00\n]/;$env->{$_}="$env->{$_}";}
die "invalid capacity\n" unless $env->{FLASH_MAXT}=~/\A[1-9][0-9]*\z/;die "nblk must be 512\n" unless $env->{FLASH_NBLK} eq '512';$env->{FLASH_ENGINE_MAXT}=$env->{FLASH_MAXT};$env->{FLASH_TRACE}='129';$env->{LC_ALL}='C';$env->{LANG}='C';
$cfg->{gpu_indices}//=[0,1,2,3,4,5];$cfg->{poll_ms}//=100;die "output exists\n" if -e $out;make_path($out);$out=abs_path($out);save("$out/config.json",$cfg);
my $lock_path=$cfg->{lock_path}//'/tmp/flash-sass-engine-validation.lock';my $lock;my $inherited=defined $lock_fd;
if($inherited){open $lock,'>&',$lock_fd or die "inherit lock fd: $!\n";my @a=stat($lock);my @b=stat($lock_path);die "wrong inherited lock inode\n" unless @a&&@b&&$a[0]==$b[0]&&$a[1]==$b[1];flock($lock,LOCK_EX|LOCK_NB) or die "inherited lock is not exclusively held\n";}
else{open $lock,'>>',$lock_path or die "open lock: $!\n";flock($lock,LOCK_EX) or die "lock: $!\n";}
save("$out/lock.json",{path=>$lock_path,inherited=>$inherited?JSON::PP::true:JSON::PP::false,fd=>fileno($lock),pid=>$$});
my(%owned,%launch);my $socket_dir;my $completed=0;
sub idle{my($stage)=@_;my $deadline=now()+($cfg->{idle_wait_seconds}//1800);my $attempt=0;
 while(1){my $r={attempt=>$attempt++,stage=>$stage};$r->{nvidia_smi}=command(['nvidia-smi']);$r->{ps}=command(['ps','-eo','pid,ppid,state,comm']);$r->{apps}=command(['nvidia-smi','--query-compute-apps=pid,gpu_uuid,process_name','--format=csv,noheader']);$r->{gpu}=command(['nvidia-smi','--query-gpu=index,uuid,utilization.gpu','--format=csv,noheader,nounits']);die "idle metadata query failed\n" if grep {$_->{exit}}@$r{qw(nvidia_smi ps apps gpu)};my %known=map {$_->{pid}=>$_}(@{$cfg->{passive_pids}//[]},values %owned);my @busy;
  for my $line(grep {/\S/}split /\n/,$r->{apps}{stdout}){my($pid)=split /,/,$line;$pid=~s/^\s+|\s+$//g;if(!exists $known{$pid}){push @busy,"unknown compute PID $pid";next;}my $p=sameproc($known{$pid});push @{$r->{known}},$p;push @busy,"PID $pid state $p->{state}" unless $p->{state}=~/\A[SI]\z/;if(exists $known{$pid}{wchan}){push @busy,"PID $pid changed wait channel" unless $p->{wchan} eq $known{$pid}{wchan};}elsif($p->{exe}=~m{/flashcore\z}){push @busy,"PID $pid is not waiting on socket" unless $p->{wchan}=~/(?:unix|sock|poll|epoll|wait_woken|skb_wait_for_more_packets)/;}}
  for my $line(grep {/\S/}split /\n/,$r->{gpu}{stdout}){my @v=split /,/,$line;for(@v){s/^\s+|\s+$//g;}die "invalid GPU utilization\n" unless @v==3&&$v[2]=~/\A\d+\z/;push @busy,"GPU $v[1] active" if $v[2]>0;}$r->{busy}=\@busy;save("$out/idle-$stage.json",$r);return unless @busy;die "host remains busy\n" if now()>$deadline;print $json->encode({waiting=>\@busy}) if $attempt%5==1;select undef,undef,undef,1;
 }
}
# Only direct, unreaped children created by this process may receive a signal.
# Permit their initial interpreter -> configured core exec transition.
sub ownedproc{my($old)=@_;my $p=proc($old->{pid});die "owned child identity changed\n" unless $p->{start_ticks} eq "$old->{start_ticks}"&&$p->{ppid}==$$&&($p->{exe} eq $cfg->{core}||$p->{exe} eq $old->{exe});return $p;}
sub cleanup{for my $name(sort keys %owned){my $p=$owned{$name};my $pid=$p->{pid};my $w=waitpid($pid,WNOHANG);next if $w==$pid||$w<0;eval{ownedproc($p);my $s=IO::Socket::UNIX->new(Type=>SOCK_STREAM,Peer=>$launch{$name}{socket},Timeout=>2);if($s){print {$s} "quit\n";close $s;}};my $end=now()+10;while(now()<$end){$w=waitpid($pid,WNOHANG);last if $w==$pid||$w<0;select undef,undef,undef,.1;}if($w==0){ownedproc($p);kill 'TERM',$pid;select undef,undef,undef,.2;$w=waitpid($pid,WNOHANG);if($w==0){ownedproc($p);kill 'KILL',$pid;waitpid($pid,0);}}}remove_tree($socket_dir) if defined($socket_dir)&&-d $socket_dir;}
local $SIG{INT}=sub{die "interrupted\n"};local $SIG{TERM}=sub{die "terminated\n"};$|=1;
my $ok=eval{
 idle('before');my $xml=command(['nvidia-smi','-q','-x']);save("$out/driver-before.json",$xml);die "full GPU XML query failed\n" if $xml->{exit}||$xml->{stdout}!~/<nvidia_smi_log>/||$xml->{stdout}!~m{</nvidia_smi_log>};
 $socket_dir=tempdir('flash-pair-XXXXXXXX',TMPDIR=>1,CLEANUP=>0);save("$out/artifacts.json",[map {hashfile($cfg->{$_})}qw(core library cubin trace_cubin dirty_patch)]);
 for my $name(qw(host vram)){idle("before-$name");my $sock="$socket_dir/$name.sock";my %child_env=(%$env,FLASH_KV_HOST=>$name eq 'host'?'1':'0',FLASH_SOCK=>$sock,FLASH_CUBIN=>$cfg->{trace_cubin});my @argv=($cfg->{core},$cfg->{ple_file},$cfg->{library},@{$cfg->{holder_manifests}});my $pid=fork();die "fork core: $!\n" unless defined $pid;
  if(!$pid){%ENV=%child_env;chdir dirname($cfg->{library}) or POSIX::_exit(126);open STDIN,'<','/dev/null' or POSIX::_exit(126);open STDOUT,'>',"$out/$name-core.log" or POSIX::_exit(126);open STDERR,'>&',\*STDOUT or POSIX::_exit(126);exec {$argv[0]} @argv;POSIX::_exit(127);}
  my $initial=proc($pid);$owned{$name}={%$initial};$launch{$name}={pid=>$pid,argv=>\@argv,launch_environment=>\%child_env,engine_reload_commands=>[],limitations=>['Legacy pinned trace format; buffers allocated equally in traced and untraced modes.'],socket=>$sock,constructor_capacity=>0+$env->{FLASH_MAXT},created_by_pid=>$$};my $end=now()+($cfg->{startup_timeout}//120);
  while(!-S $sock){my $w=waitpid($pid,WNOHANG);if($w==$pid){delete $owned{$name};die "$name core exited before socket: $?\n";}die "$name startup timeout\n" if now()>$end;select undef,undef,undef,.1;}
  my $actual=proc($pid);die "unexpected core executable\n" unless $actual->{exe} eq $cfg->{core};$owned{$name}={%$actual};delete $owned{$name}{wchan};$launch{$name}{process}=$actual;
  my %actual_env;for(split /\0/,read_text("/proc/$pid/environ")){my($k,$v)=split /=/,$_,2;$actual_env{$k}=$v if defined $v;}for my $k(keys %child_env){die "core environment differs at $k\n" unless defined($actual_env{$k})&&$actual_env{$k} eq $child_env{$k};}$launch{$name}{observed_environment}=\%actual_env;
  $launch{$name}{config}=one($sock,'config');save("$out/core-records.json",\%launch);print $json->encode({ready=>$name,pid=>$pid,config=>$launch{$name}{config}});
 }
 my %configs;for my $name(qw(host vram)){my @parts=split /\s+/,$launch{$name}{config};shift @parts;my %c=map {split /=/,$_,2}grep {/=/}@parts;die "wrong constructed capacity or placement\n" unless $c{maxt}==$env->{FLASH_MAXT}&&$c{kv_host}==($name eq 'host'?1:0)&&$c{trace_tokens}==129;$configs{$name}=\%c;}
 for my $k(keys %{$configs{host}}){next if $k eq 'kv_host';die "unmatched core config $k\n" unless defined($configs{vram}{$k})&&$configs{host}{$k} eq $configs{vram}{$k};}
 save("$out/startup.json",{status=>'PASS',configs=>\%configs,constructor_capacity=>0+$env->{FLASH_MAXT},private_cores=>JSON::PP::true});
 unless($startup){my $module=dirname(abs_path($0)).'/decode_pair_capture.pl';require $module;DecodePairCapture::run_capture($cfg,$out,\%launch,\%owned);}$completed=1;1;
};my $error=$@;my $clean=eval{cleanup();1;};$error.=$@ unless $clean;save("$out/exit.json",{exit=>$ok&&$clean?0:1,completed=>$completed?JSON::PP::true:JSON::PP::false,cleanup_success=>$clean?JSON::PP::true:JSON::PP::false,error=>"$error"});die $error unless $ok&&$clean;exit 0;
